    stock = {"A": 5}
    items = [{"sku": "A", "price_cents": 1000, "qty": 3}]
    def charge(total):
        return True
    status, body = checkout({"items": items}, stock, charge)
    assert status == 200
    assert stock["A"] == 2  # stock reduced

